        lines.append('            type: \'' + section['type'] + '\',')
        if 'title' in section:
            title = section['title'].replace("'", "\\'")
            lines.append('            title: \'' + title + '\',')
        if 'content' in section:
            content = section['content'].replace("'", "\\'").replace("\n", "\\n")
            lines.append('            content: \'' + content + '\',')
